  {{ds:component/card|href={{cms:item/25d4407d-805e-4f94-98d3-652ae78978d4}}|tag=Endpoint|title=Events|description=Query and replay events that have flowed through a pipeline.}}
  {{ds:component/card|href={{cms:item/bb137086-ba77-4d11-87e6-36de66c72b7d}}|tag=Endpoint|title=Webhooks|description=Subscribe to platform lifecycle events over outbound HTTP.}}
